db.products.insertOne({
    name: 'Wireless Mouse',
    category: 'Electronics',
    price: 29.99,
    inStock: true,
    createdAt: new Date()
});

db.products.insertMany([
    { name: 'Mechanical Keyboard', category: 'Electronics', price: 99.99, inStock: true },
    { name: 'USB-C Cable', category: 'Accessories', price: 12.99, inStock: false }
]);

db.products.find(
    { category: 'Electronics' },
    { name: 1, price: 1, _id: 0 }
).sort({ price: -1 }).limit(5);

db.products.find({
    price: { $gte: 20, $lte: 100 },
    category: { $in: ['Electronics', 'Accessories'] }
});

db.products.find({
    $or: [
        { category: 'Electronics' },
        { price: { $lt: 15 } }
    ],
    $and: [
        { inStock: true }
    ]
});

db.products.updateOne(
    { name: 'Wireless Mouse' },
    {
        $inc: { stockCount: 10 },
        $set: { lastRestocked: new Date(), inStock: true }
    }
);

db.products.updateOne(
    { _id: 'prod-101' },
    {
        $addToSet: { tags: { $each: ['gadget', 'wireless', 'featured'] } }
    }
);

db.products.deleteMany({ inStock: false, stockCount: 0 });

db.products.bulkWrite([
    { insertOne: { document: { name: 'Item A', price: 10 } } },
    { updateOne: { filter: { name: 'Item B' }, update: { $set: { price: 15 } } } }
]);

db.products.aggregate([
    { $match: { category: 'Electronics', inStock: true } },
    {
        $project: {
            productName: '$name',
            formattedPrice: { $concat: ['$', { $toString: '$price' }] },
            _id: 0
        }
    }
]);

db.products.aggregate([
    {
        $group: {
            _id: '$category',
            totalProducts: { $sum: 1 },
            avgPrice: { $avg: '$price' },
            totalInventoryValue: { $sum: { $multiply: ['$price', '$stockCount'] } }
        }
    },
    { $sort: { totalInventoryValue: -1 } }
]);

db.products.aggregate([
    { $unwind: '$tags' },
    {
        $group: {
            _id: '$tags',
            tagCount: { $sum: 1 }
        }
    },
    { $sort: { tagCount: -1 } }
]);

db.orders.aggregate([
    {
        $lookup: {
            from: 'users',
            localField: 'userId',
            foreignField: '_id',
            as: 'customerDetails'
        }
    },
    { $unwind: '$customerDetails' },
    {
        $project: {
            orderId: '$_id',
            amount: 1,
            customerName: '$customerDetails.name',
            customerEmail: '$customerDetails.email'
        }
    }
]);

db.users.createIndex({ email: 1 }, { unique: true });

db.products.createIndex(
    { category: 1, price: -1 },
    { name: 'idx_category_price' }
);

console.log(db.products.getIndexes());

db.products.createIndex({ name: 'text', description: 'text' });

db.products.find(
    { $text: { $search: 'wireless keyboard' } },
    { score: { $meta: 'textScore' } }
).sort({ score: { $meta: 'textScore' } });

db.stores.createIndex({ location: '2dsphere' });

db.stores.find({
    location: {
        $near: {
            $geometry: {
                type: 'Point',
                coordinates: [-73.9667, 40.78] // [longitude, latitude]
            },
            $maxDistance: 5000 // meters
        }
    }
});

db.createCollection('validated_users', {
    validator: {
        $jsonSchema: {
            bsonType: 'object',
            required: ['name', 'email', 'role'],
            properties: {
                name: {
                    bsonType: 'string',
                    description: 'name must be a string'
                },
                email: {
                    bsonType: 'string',
                    pattern: '^.+@.+$',
                    description: 'email must be valid'
                },
                role: {
                    enum: ['admin', 'user', 'developer'],
                    description: 'role must be an allowed enum string'
                }
            }
        }
    }
});

db.users.insertOne({
    name: 'Alex River',
    email: 'alex@bytecode.dev',
    // Embedded Document Array (1-to-Few)
    addresses: [
        { type: 'home', street: '123 Tech Lane', city: 'San Francisco', zip: '94105' }
    ],
    // Referenced Array (1-to-Many)
    orderIds: [
        ObjectId('60c72b2f9b1d8b2a3c4d5e6f')
    ]
});

const session = db.getMongo().startSession();
session.startTransaction();

try {
    const accounts = session.getDatabase('bank').accounts;
    accounts.updateOne({ _id: 'acc-1' }, { $inc: { balance: -100 } });
    accounts.updateOne({ _id: 'acc-2' }, { $inc: { balance: 100 } });

    session.commitTransaction();
    console.log('Transaction Committed Successfully.');
} catch (error) {
    session.abortTransaction();
    console.error('Transaction Aborted:', error);
} finally {
    session.endSession();
}

const fileMetadata = db.fs.files.findOne({ filename: 'video_archive.mp4' });

if (fileMetadata) {
    const chunks = db.fs.chunks.find({ files_id: fileMetadata._id }).count();
    console.log(`File Size: ${fileMetadata.length} bytes split across ${chunks} GridFS chunks.`);
}

const explanation = db.products.find({
    category: 'Electronics',
    price: { $lt: 50 }
}).explain('executionStats');

const stats = explanation.executionStats;
console.log(`Execution Stage: ${explanation.queryPlanner.winningPlan.stage}`);
console.log(`Docs Examined: ${stats.totalDocsExamined} | Keys Examined: ${stats.totalKeysExamined}`);

// 1. Create Collection with Validator
db.createCollection('inventory_items', {
    validator: {
        $jsonSchema: {
            bsonType: 'object',
            required: ['sku', 'name', 'quantity', 'price'],
            properties: {
                sku: { bsonType: 'string' },
                quantity: { bsonType: 'int', minimum: 0 },
                price: { bsonType: 'double', minimum: 0 }
            }
        }
    }
});

// 2. Create Compound Index
db.inventory_items.createIndex({ sku: 1 }, { unique: true });
db.inventory_items.createIndex({ category: 1, quantity: 1 });

// 3. Stock Report Aggregation Pipeline
const report = db.inventory_items.aggregate([
    {
        $group: {
            _id: '$category',
            totalItems: { $sum: 1 },
            totalQuantity: { $sum: '$quantity' },
            valuation: { $sum: { $multiply: ['$price', '$quantity'] } }
        }
    },
    { $sort: { valuation: -1 } }
]);

console.log('Stock Report Aggregation Complete.');
